CREATE OR REPLACE FUNCTION public.agent_audit_ids_valid(p_ids jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_typeof(p_ids) = 'object' and not exists (
    select 1 from jsonb_each(p_ids) as kv(key, value)
