            when 'array' then not exists (select 1 from jsonb_array_elements(kv.value) e
                                          where jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
            else false
          end);
$function$;

